const webhook = $('Webhook').first().json;
const postArr = $('Get Post').first().json;
const acctArr = $('Get Platform Account').first().json;
const post = Array.isArray(postArr) ? postArr[0] : postArr;
const account = Array.isArray(acctArr) ? acctArr[0] : acctArr;
const platform = webhook.platform || post?.plataforma || 'linkedin';
const content = post?.contenido || post?.titulo || '';

if (!account || account.is_mock) {
  return [{ json: {
    isMock: true,
    success: true,
    externalId: `mock_${platform}_${Date.now()}`,
    publishUrl: `https://mock.${platform}.com/post/${Date.now()}`,
    publishApiUrl: '',
    authHeader: '',
    linkedinProtocol: '',
    publishBody: '{}',
    platform
  }}];
}

const token = account.access_token || '';
const accountId = account.account_id || '';
let publishApiUrl, authHeader, linkedinProtocol, publishBody;

switch (platform) {
  case 'linkedin':
    publishApiUrl = 'https://api.linkedin.com/v2/ugcPosts';
    authHeader = `Bearer ${token}`;
    linkedinProtocol = '2.0.0';
    publishBody = JSON.stringify({
      author: `urn:li:organization:${accountId}`,
      lifecycleState: 'PUBLISHED',
      specificContent: {
        'com.linkedin.ugc.ShareContent': {
          shareCommentary: { attributes: [], text: content },
          shareMediaCategory: 'NONE'
        }
      },
      visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' }
    });
    break;
  case 'twitter':
    publishApiUrl = 'https://api.twitter.com/2/tweets';
    authHeader = `Bearer ${token}`;
    linkedinProtocol = '';
    publishBody = JSON.stringify({ text: content.substring(0, 280) });
    break;
  case 'instagram':
    publishApiUrl = `https://graph.facebook.com/v18.0/${accountId}/media`;
    authHeader = '';
    linkedinProtocol = '';
    publishBody = JSON.stringify({ caption: content, media_type: 'FEED', access_token: token });
    break;
  default:
    publishApiUrl = `https://graph.facebook.com/v18.0/${accountId}/feed`;
    authHeader = '';
    linkedinProtocol = '';
    publishBody = JSON.stringify({ message: content, access_token: token });
}

return [{ json: { isMock: false, success: null, externalId: null, publishUrl: null, publishApiUrl, authHeader, linkedinProtocol, publishBody, platform } }];

const input = $json;
const platform = $('Build Publish Request').first().json.platform;
let success, externalId, publishUrl, errorMsg;

if (input.isMock === true) {
  success = true;
  externalId = input.externalId;
  publishUrl = input.publishUrl;
  errorMsg = null;
} else if (input.error || (input.status && input.status >= 400)) {
  success = false;
  externalId = null;
  publishUrl = null;
  errorMsg = input.message || (input.error && input.error.message) || JSON.stringify(input).substring(0, 200);
} else {
  switch (platform) {
    case 'linkedin':
      externalId = input.id || null;
      publishUrl = externalId ? `https://www.linkedin.com/feed/update/${externalId}` : null;
      break;
    case 'twitter':
      externalId = (input.data && input.data.id) || input.id || null;
      publishUrl = externalId ? `https://twitter.com/i/web/status/${externalId}` : null;
      break;
    default:
      externalId = input.id || null;
      publishUrl = null;
  }
  success = !!externalId;
  errorMsg = success ? null : 'No external ID returned from platform API';
}

return [{ json: { success, externalId, publishUrl, errorMsg, platform, isMock: false } }];
